// #43ca04 (№30) «Android - בפרופיל האישי הערכים של השורות לא מוצגים בזום 200%» — עבר QA 09.11.
//   מה רצוי: «בזום 200% בכל שורה מוצגים גם הכותרת וגם הערך (למשל הערך עובר לשורה שנייה מתחת לכותרת), בלי שהערך ייעלם או יקוצר לנקודות».
// Факт 09.11 (Pixel 6, wm density 840, аккаунт «QA reg 0311»): «אשכנז», «1.1.1990», «פתח / תקווה», «להתחזק», «כל יום» — под заголовками (14ad0d8).
// Значения берутся из подписи строки «<поле>: <значение>. מעבר לשלב כדי לשנות» (не зависят от аккаунта).
// Кейс: .qa/tests/zoom-200/Z2-06-profile-values.md. Только просмотр.
import { driver, expect } from '@wdio/globals';
import { scrollToText } from '../../helpers/ui.ts';
import { goHome, openProfile, profileValue, type UiNode } from '../_lib/readiness-1910.ts';
import { skipWith } from '../_lib/app-0710.ts';
import { zoomOn, zoomOff, textNode, insideScreenX, notTruncated, saveShot } from '../_lib/app-0911.ts';

const FIELDS = ['נוסח תפילה', 'תאריך לידה', 'מיקום', 'היעד שלי', 'רמת התחזקות'];

async function rowPair(field: string, value: string): Promise<{ t: UiNode; v: UiNode }> {
  await scrollToText(field);
  return { t: await textNode(field), v: await textNode(value) };
}

describe('09.11 — зум 200% (Android): «פרופיל אישי» — значения строк (#43ca04)', () => {
  before(function () { if (!driver.isAndroid) skipWith(this, 'зум через wm density — только Android'); });
  after(async () => { if (driver.isAndroid) await zoomOff(); });

  it('Z2-06 При wm density 840 в «פרטים אישיים» у «נוסח תפילה», «תאריך לידה», «מיקום», «היעד שלי», «רמת התחזקות» видны и заголовок, и значение — не «..», не пусто #43ca04 @android @prod-safe @manual-check', async () => {
    await openProfile();
    const values: Record<string, string> = {};
    const normal: Record<string, UiNode> = {};
    for (const f of FIELDS) {
      values[f] = await profileValue(f);
      expect(values[f]).not.toBe('');
      normal[f] = (await rowPair(f, values[f])).v;
    }

    await goHome();
    await zoomOn();
    await openProfile();
    for (const f of FIELDS) {
      const { t, v } = await rowPair(f, values[f]);
      await saveShot(`q31-profile-${FIELDS.indexOf(f) + 1}.png`);
      console.log(`[Q-31] «${f}» → «${values[f]}»: значение ${v.w}×${v.h} (обычн. ${normal[f].w}×${normal[f].h})`);
      expect(await insideScreenX(t)).toBe(true);
      expect(await insideScreenX(v)).toBe(true);
      expect(v.w).toBeGreaterThan(0);
      expect(notTruncated(v, normal[f])).toBe(true);
    }
    // Глазами по q31-profile-*.png: значение целиком (например «פתח / תקווה»), нет «..».
  });
});
